113	/// Common base class shared among various IRBuilders.
114	class IRBuilderBase {
115	  /// The DebugLoc that will be applied to instructions inserted by this
116	  /// builder.
117	  DebugLoc StoredDL;
118	
119	protected:
120	  BasicBlock *BB;
121	  BasicBlock::iterator InsertPt;
122	  LLVMContext &Context;
123	  const IRBuilderFolder &Folder;
124	  const IRBuilderDefaultInserter &Inserter;
125	
126	  MDNode *DefaultFPMathTag;
127	  FastMathFlags FMF;
128	
129	  bool IsFPConstrained = false;
130	  fp::ExceptionBehavior DefaultConstrainedExcept = fp::ebStrict;
131	  RoundingMode DefaultConstrainedRounding = RoundingMode::Dynamic;
132	
133	  ArrayRef<OperandBundleDef> DefaultOperandBundles;
134	
135	public:
136	  IRBuilderBase(LLVMContext &context, const IRBuilderFolder &Folder,
137	                const IRBuilderDefaultInserter &Inserter, MDNode *FPMathTag,
138	                ArrayRef<OperandBundleDef> OpBundles)
139	      : Context(context), Folder(Folder), Inserter(Inserter),
140	        DefaultFPMathTag(FPMathTag), DefaultOperandBundles(OpBundles) {
141	    ClearInsertionPoint();
142	  }
143	
144	  /// Insert and return the specified instruction.
145	  template<typename InstTy>
146	  InstTy *Insert(InstTy *I, const Twine &Name = "") const {
147	    Inserter.InsertHelper(I, Name, InsertPt);
148	    SetInstDebugLocation(I);
149	    return I;
150	  }
151	
152	  /// No-op overload to handle constants.
153	  Constant *Insert(Constant *C, const Twine& = "") const {
154	    return C;
155	  }
156	
157	  Value *Insert(Value *V, const Twine &Name = "") const {
158	    if (Instruction *I = dyn_cast<Instruction>(V))
159	      return Insert(I, Name);
160	    assert(isa<Constant>(V));
161	    return V;
162	  }
