323	#ifndef NDEBUG
324	    std::optional<StringRef> RoundingStr =
325	        convertRoundingModeToStr(NewRounding);
326	    assert(RoundingStr && "Garbage strict rounding mode!");
327	#endif
328	    DefaultConstrainedRounding = NewRounding;
