                                      L, R, FMFSource, Name, FPMD);

    if (Value *V =
            Folder.FoldBinOpFMF(Instruction::FAdd, L, R, FMFSource.get(FMF)))
      return V;
    Instruction *I =
        setFPAttrs(BinaryOperator::CreateFAdd(L, R), FPMD, FMFSource.get(FMF));
    return Insert(I, Name);
