953	CallInst *IRBuilderBase::CreateIntrinsicWithoutFolding(Type *RetTy,
954	                                                       Intrinsic::ID ID,
955	                                                       ArrayRef<Value *> Args,
956	                                                       FMFSource FMFSource,
957	                                                       const Twine &Name) {
958	  Module *M = BB->getModule();
959	  SmallVector<Type *> ArgTys = llvm::map_to_vector(Args, &Value::getType);
960	  Function *Fn = Intrinsic::getOrInsertDeclaration(M, ID, RetTy, ArgTys);
961	  return createCallHelper(Fn, Args, Name, FMFSource);
962	}
