964	Value *IRBuilderBase::CreateIntrinsic(Intrinsic::ID ID,
965	                                      ArrayRef<Type *> OverloadTypes,
966	                                      ArrayRef<Value *> Args,
967	                                      FMFSource FMFSource, const Twine &Name,
968	                                      ArrayRef<OperandBundleDef> OpBundles,
969	                                      function_ref<void(CallInst *)> SetFn) {
970	  Type *RetTy = Intrinsic::getType(Context, ID, OverloadTypes)->getReturnType();
971	  if (Value *V = Folder.FoldIntrinsic(ID, Args, RetTy, FMFSource.get(FMF),
972	                                      GetInsertBlock()->getParent()))
973	    return V;
974	  CallInst *CI = CreateIntrinsicWithoutFolding(ID, OverloadTypes, Args,
975	                                               FMFSource, Name, OpBundles);
976	  SetFn(CI);
977	  return CI;
978	}
