1042	Value *IRBuilderBase::CreateNAryOp(unsigned Opc, ArrayRef<Value *> Ops,
1043	                                   const Twine &Name, MDNode *FPMathTag) {
1044	  if (Instruction::isBinaryOp(Opc)) {
1045	    assert(Ops.size() == 2 && "Invalid number of operands!");
1046	    return CreateBinOp(static_cast<Instruction::BinaryOps>(Opc),
1047	                       Ops[0], Ops[1], Name, FPMathTag);
1048	  }
1049	  if (Instruction::isUnaryOp(Opc)) {
1050	    assert(Ops.size() == 1 && "Invalid number of operands!");
1051	    return CreateUnOp(static_cast<Instruction::UnaryOps>(Opc),
1052	                      Ops[0], Name, FPMathTag);
1053	  }
1054	  llvm_unreachable("Unexpected opcode!");
1055	}
