1057	CallInst *IRBuilderBase::CreateConstrainedFPCast(
1058	    Intrinsic::ID ID, Value *V, Type *DestTy, FMFSource FMFSource,
1059	    const Twine &Name, MDNode *FPMathTag, std::optional<RoundingMode> Rounding,
1060	    std::optional<fp::ExceptionBehavior> Except) {
1061	  Value *ExceptV = getConstrainedFPExcept(Except);
1062	
1063	  FastMathFlags UseFMF = FMFSource.get(FMF);
1064	
1065	  CallInst *C;
1066	  if (Intrinsic::hasConstrainedFPRoundingModeOperand(ID)) {
1067	    Value *RoundingV = getConstrainedFPRounding(Rounding);
1068	    C = CreateIntrinsicWithoutFolding(
1069	        ID, {DestTy, V->getType()}, {V, RoundingV, ExceptV}, nullptr, Name, {});
1070	  } else
1071	    C = CreateIntrinsicWithoutFolding(ID, {DestTy, V->getType()}, {V, ExceptV},
1072	                                      nullptr, Name, {});
1073	  setConstrainedFPCallAttr(C);
1074	
